INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(52017, 0, 0, 'Oh, you will regret doing that, Dear.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66462'),
(52066, 0, 0, 'First, we put this here, and then this... here...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66997'),
(52066, 1, 0, 'Then all it takes is, Ah! Damn thing!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66998'),
(52066, 2, 0, 'There it is, I\'ve done it, here you are, my work is complete!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66999'),
(52119, 0, 0, 'Executed?! Do you know who it is you speak to?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67014'),
(52119, 1, 0, 'Do you know who it is you\'re threatening?!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67015'),
(52119, 2, 0, 'I shall destroy you and all others who try to stop me!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67016');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030035, 'What? She told this to a stranger? Oh by the light, this is... this is worse than I thought. Please, speak to Marge Blackwood, she is the investigator in this town, and responsible for several cases currently. Speak to her, she will explain it all. Somehow I think I\'m sleeping outside tonight anyhow.', 'What? She told this to a stranger? Oh by the light, this is... this is worse than I thought. Please, speak to Marge Blackwood, she is the investigator in this town, and responsible for several cases currently. Speak to her, she will explain it all. Somehow I think I\'m sleeping outside tonight anyhow.', 1, 0);
